insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_20_v1'
from (values
('127.112.d.1.A',3,'A packaged rooftop unit differs from a split system because all its components are in:','["One cabinet", "Separate rooms", "Underground vaults", "Two buildings"]'::jsonb,0,'Packaged units are self-contained.','original'),
('127.112.d.1.A',4,'A commercial chilled-water system cools air by circulating:','["Sand through ducts", "Cold water to coils in air handlers", "Hot gas to the roof", "Steam to the walls"]'::jsonb,1,'Chilled water carries cooling.','original'),
('127.112.d.1.B',3,'A large office tower is most likely served by a:','["Single portable fan", "Window unit per floor", "Central chilled-water plant", "Fireplace"]'::jsonb,2,'Large buildings use central plants.','original'),
('127.112.d.1.B',4,'A small strip-mall store is commonly cooled by a:','["Cooling tower plant", "Absorption chiller for the whole block", "Steam boiler loop", "Rooftop packaged unit"]'::jsonb,3,'Small stores use rooftop units.','original'),
('127.112.d.1.C',3,'Commercial air system capacity is usually stated in:','["Tons or BTU per hour", "Volts per foot", "Gallons per mile", "Pounds per inch"]'::jsonb,0,'Capacity is cooling output.','original'),
('127.112.d.1.C',4,'A 5-ton unit provides how many BTU per hour of cooling?','["600,000", "60,000", "12,000", "5,000"]'::jsonb,1,'5 x 12,000 = 60,000.','original'),
('127.112.d.2.A',3,'Complete combustion of natural gas produces carbon dioxide and:','["Carbon monoxide", "Soot", "Water vapor", "Sulfur"]'::jsonb,2,'Complete burn yields CO2 and H2O.','original'),
('127.112.d.2.A',4,'Incomplete combustion is a hazard mainly because it creates:','["Cooler flames", "More nitrogen", "Extra oxygen", "Carbon monoxide"]'::jsonb,3,'CO is poisonous.','original'),
('127.112.d.2.B',3,'Flue gas from a gas furnace contains mostly nitrogen, carbon dioxide, and:','["Water vapor", "Ammonia", "Chlorine", "Fresh oxygen only"]'::jsonb,0,'Flue gas composition.','original'),
('127.112.d.2.B',4,'Flue gases are vented outdoors to keep them from:','["Raising voltage", "Entering the occupied space", "Cooling the burners", "Wetting the duct"]'::jsonb,1,'Venting protects occupants.','original'),
('127.112.d.2.C',3,'A furnace vent system includes a vent pipe, connector, and a:','["Condensate pump only", "Humidifier", "Termination cap", "Fuse box"]'::jsonb,2,'Terminations finish the vent.','original'),
('127.112.d.2.C',4,'A draft hood on a natural-draft furnace helps by:','["Heating the room", "Storing fuel", "Filtering air", "Relieving excess draft and back-drafts"]'::jsonb,3,'The hood stabilizes draft.','original'),
('127.112.d.2.D',3,'When selecting a vent for a furnace, the installer follows the:','["Manufacturer instructions and fuel gas code", "Color of the furnace", "Lowest price", "Neighbor''s advice"]'::jsonb,0,'Codes govern venting.','original'),
('127.112.d.2.D',4,'A Category I vent is used with furnaces that operate with:','["Condensing flue gases", "Non-positive vent pressure and flue gas above dew point", "No flue at all", "Positive pressure at all times"]'::jsonb,1,'Category definitions.','original'),
('127.112.d.2.E',3,'Proper combustion in a gas burner is judged by flame color, which should be mostly:','["Yellow and sooty", "Black", "Blue", "Red"]'::jsonb,2,'Blue flame is efficient.','original'),
('127.112.d.2.E',4,'A burner with a lazy yellow flame often needs more:','["Gas pressure", "Fuel oil", "Water", "Primary air"]'::jsonb,3,'Yellow flame means too little air.','original'),
('127.112.d.2.F',3,'A condensing furnace vent is usually made of:','["PVC plastic", "Aluminum foil", "Cast iron", "Single-wall galvanized steel"]'::jsonb,0,'Cool flue gas allows plastic.','original'),
('127.112.d.2.F',4,'Venting for a high-efficiency furnace must be sloped to:','["Fill the vent", "Drain condensate back to the furnace", "Heat the attic", "Pool water"]'::jsonb,1,'Condensate drains properly.','original'),
('127.112.d.2.G',3,'A barometric damper on a flue pipe controls:','["Humidity only", "Fuel pressure", "Draft", "Voltage"]'::jsonb,2,'Dampers regulate draft.','original'),
('127.112.d.2.G',4,'A draft inducer is a fan that:','["Pumps refrigerant", "Mixes fuel", "Cools the room", "Pulls flue gases through the heat exchanger"]'::jsonb,3,'Inducers create draft.','original'),
('127.112.d.2.H',3,'Vent size for a gas appliance is chosen from tables based on input rating and vent:','["Height and lateral length", "Location of thermostat", "Brand", "Paint color"]'::jsonb,0,'Tables set sizes.','original'),
('127.112.d.2.H',4,'A vent that is too large for a small appliance can cause:','["Stronger draft", "Condensation and poor draft", "Lower pressure", "Faster heating"]'::jsonb,1,'Oversized vents cool gases.','original'),
('127.112.d.2.I',3,'A heat anticipator in a thermostat is set to match the:','["Room color", "Fuel type", "Current draw of the control circuit", "Duct size"]'::jsonb,2,'Anticipator matches amps.','original'),
('127.112.d.2.I',4,'Setting the anticipator too low can cause the furnace to:','["Overheat the thermostat", "Run constantly", "Stay off", "Short cycle"]'::jsonb,3,'Wrong setting changes cycling.','original'),
('127.112.d.3.A',3,'A closed hydronic system recirculates:','["The same water in a sealed loop", "Steam only", "Air", "Fresh water each time"]'::jsonb,0,'Closed means sealed.','original'),
('127.112.d.3.A',4,'The unit of heat energy commonly used in hydronic work is the:','["Lumen", "BTU", "Newton", "Volt"]'::jsonb,1,'BTU measures heat.','original'),
('127.112.d.3.B',3,'Major parts of a hot-water heating system include the boiler, pump, and:','["Spark plugs", "Condenser coil", "Radiators or baseboard units", "Compressor"]'::jsonb,2,'Emitters deliver heat.','original'),
('127.112.d.3.B',4,'The expansion tank in a hot-water system absorbs:','["Voltage spikes", "Gas leaks", "Sound", "Water volume changes as it heats"]'::jsonb,3,'Tanks cushion expansion.','original'),
('127.112.d.3.C',3,'The circulator pump in a hot-water system moves:','["Heated water through the piping", "Refrigerant", "Fuel to the burner", "Air through filters"]'::jsonb,0,'Pumps circulate water.','original'),
('127.112.d.3.C',4,'An air vent on a hydronic loop removes:','["Heat only", "Trapped air that blocks flow", "Fuel", "Water"]'::jsonb,1,'Air stops circulation.','original'),
('127.112.d.3.D',3,'Before working on a hot boiler, a technician should let the system:','["Be filled with air", "Stay under pressure", "Cool and relieve pressure", "Run hotter"]'::jsonb,2,'Scalding is a hazard.','original'),
('127.112.d.3.D',4,'The relief valve on a boiler discharges to prevent:','["Cold rooms", "Low flow", "Wet floors", "Dangerous over-pressure"]'::jsonb,3,'Safety valve.','original'),
('127.112.d.3.E',3,'To start a hot-water system after service, the technician first makes sure the system is:','["Filled with water and purged of air", "Empty", "Disconnected", "Wet with oil"]'::jsonb,0,'Never fire a dry boiler.','original'),
('127.112.d.3.E',4,'A boiler aquastat controls:','["Duct size", "Water temperature", "Air speed", "Gas pressure"]'::jsonb,1,'It holds temperature setpoint.','original'),
('127.112.d.3.F',3,'Low-pressure boilers operate at no more than:','["150 psi", "1000 psi", "15 psi for steam", "500 psi"]'::jsonb,2,'Low-pressure steam limit.','original'),
('127.112.d.3.F',4,'Before blowing down a low-water cutoff, the technician must make sure that:','["All valves are closed", "The burner is firing high", "The boiler is hot and unattended", "Everyone clear of the discharge and procedures are followed"]'::jsonb,3,'Safe procedure.','original'),
('127.112.d.3.G',3,'Common hydronic piping layouts include series loop, one-pipe, and:','["Two-pipe systems", "Zero-pipe", "Seven-pipe", "Open-top"]'::jsonb,0,'Standard layouts.','original'),
('127.112.d.3.G',4,'A primary-secondary piping arrangement lets boilers and loads:','["Run without water", "Have independent flow", "Use the same gas line", "Share the same pump only"]'::jsonb,1,'Hydraulic separation.','original'),
('127.112.d.3.H',3,'The pressure difference across a circulator pump is read with:','["A thermometer", "An ohmmeter", "Two gauges, one at each side", "A level"]'::jsonb,2,'Differential pressure.','original'),
('127.112.d.3.H',4,'If the pressure drop across a pump is zero, the pump may be:','["Too small", "Overheated", "Working perfectly", "Not moving water"]'::jsonb,3,'Zero differential suggests no flow.','original'),
('127.112.d.3.I',3,'Heating water flow in gallons per minute is found by dividing the heat load by 500 times the:','["Temperature drop", "Boiler weight", "Pump color", "Pipe length"]'::jsonb,0,'GPM = BTUH / (500 x delta T).','original'),
('127.112.d.3.I',4,'A 60,000 BTUH load with a 20-degree drop needs how many gpm?','["12", "6", "3", "60"]'::jsonb,1,'60,000 / (500 x 20) = 6.','original'),
('127.112.d.3.J',3,'A pump is selected by matching the flow rate needed to the:','["Pipe color", "Building age", "Head loss of the system", "Fuel brand"]'::jsonb,2,'Pump curve meets system curve.','original'),
('127.112.d.3.J',4,'A pump curve plots head against:','["Temperature", "Voltage", "Noise", "Flow rate"]'::jsonb,3,'Pump curves show head vs flow.','original'),
('127.112.d.4.A',3,'Very low indoor humidity in winter can cause:','["Dry skin and static shocks", "Condensation", "Mold on windows", "Stronger breathing"]'::jsonb,0,'Dry air is uncomfortable.','original'),
('127.112.d.4.A',4,'Too much indoor humidity can promote:','["Static shocks", "Mold growth", "Dry throats", "Cracked skin"]'::jsonb,1,'Moisture grows mold.','original'),
('127.112.d.4.B',3,'A bypass humidifier uses air from the furnace to:','["Cool the burner", "Recover refrigerant", "Evaporate water into the airstream", "Filter dust"]'::jsonb,2,'Bypass types add moisture.','original'),
('127.112.d.4.B',4,'A steam humidifier makes moisture by:','["Spraying cold water", "Freezing water", "Condensing gas", "Boiling water with electric elements"]'::jsonb,3,'Steam humidifiers boil water.','original'),
('127.112.d.4.C',3,'The water supply to a humidifier should include a:','["Shutoff valve and drain", "Thermostat", "Light bulb", "Spark plug"]'::jsonb,0,'Service valves needed.','original'),
('127.112.d.4.C',4,'Mineral buildup in a humidifier is cleaned to restore:','["Voltage", "Proper output", "Duct size", "Fuel supply"]'::jsonb,1,'Scale lowers performance.','original'),
('127.112.d.4.D',3,'A MERV rating describes how well a filter:','["Cools air", "Dries air", "Captures particles", "Heats air"]'::jsonb,2,'Higher MERV catches more.','original'),
('127.112.d.4.D',4,'Compared with a MERV 4 filter, a MERV 13 filter captures:','["Nothing", "Less dust", "Only large lint", "Smaller particles"]'::jsonb,3,'Higher ratings capture smaller particles.','original'),
('127.112.d.4.E',3,'When installing a furnace filter, the airflow arrow should point:','["Toward the blower", "Away from the blower", "Toward the ceiling", "Toward the room"]'::jsonb,0,'Arrow shows flow direction.','original'),
('127.112.d.4.E',4,'A clogged filter reduces airflow and can cause the coil to:','["Cool faster", "Freeze up", "Save energy", "Run hotter"]'::jsonb,1,'Low airflow freezes coils.','original'),
('127.112.d.4.F',3,'A manometer measuring across a filter shows the filter''s:','["Age", "Cost", "Pressure drop", "Color"]'::jsonb,2,'Static pressure drop.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
