('127.113.d.1.C',3,'Besides medical bills, accidents cost a company through lost time and:','["Faster work", "More profit", "Reduced productivity", "Lower rates"]'::jsonb,2,'Accidents have costs.','original'),
('127.113.d.1.C',4,'Direct costs of an injury include medical care and:','["Cheaper tools", "Paint", "Extra vacation", "Workers'' compensation"]'::jsonb,3,'Direct costs.','original'),
('127.113.d.1.D',3,'Hard hats protect the head from:','["Falling objects", "Rain on skin", "Light", "Hunger"]'::jsonb,0,'PPE use.','original'),
('127.113.d.1.D',4,'PPE should be inspected before use for:','["Brand", "Damage or wear", "Price", "Color"]'::jsonb,1,'Check gear.','original'),
('127.113.d.1.E',3,'A hazard that plumbers face working with soldering is:','["Sunburn indoors", "Dizziness from cold", "Burns from hot tools and pipe", "Frostbite"]'::jsonb,2,'Heat hazard.','original'),
