('127.113.d.2.B',4,'A plumbing license shows that a person has met:','["Height only", "Age only", "Color rules", "State qualification requirements"]'::jsonb,3,'Licensing.','original'),
('127.113.d.2.C',3,'A trade association for plumbers is the:','["Plumbing-Heating-Cooling Contractors Association", "Art Guild", "Music Teachers Club", "Garden Society"]'::jsonb,0,'Industry groups.','original'),
